const express = require('express');
const path = require('path');
const fs = require('fs');
const crypto = require('crypto');
const Database = require('better-sqlite3');

const app = express();
const PORT = Number(process.env.PORT || 3000);
// Vercel's deployed application directory is read-only. Keep local data beside
// the app, but use its writable temporary directory when running as a function.
// DATABASE_PATH can point at a writable persistent volume in other environments.
const dbPath = process.env.DATABASE_PATH || path.join(process.env.VERCEL ? '/tmp' : __dirname, 'club.db');
fs.mkdirSync(path.dirname(dbPath), { recursive: true });
const db = new Database(dbPath);
db.pragma('journal_mode = WAL');
db.pragma('foreign_keys = ON');
app.use(express.json());
app.use(express.static(path.join(__dirname, 'public')));

const today = () => new Date().toISOString().slice(0,10);
const num = v => Number(v || 0);
const legacyHash = s => crypto.createHash('sha256').update(String(s)).digest('hex');
const hashPassword = password => {
 const salt=crypto.randomBytes(16).toString('hex');
 return `scrypt$${salt}$${crypto.scryptSync(String(password),salt,64).toString('hex')}`;
};
const verifyPassword = (password, stored) => {
 if(!stored?.startsWith('scrypt$')) return legacyHash(password)===stored;
 const [,salt,digest]=stored.split('$');
 const actual=crypto.scryptSync(String(password),salt,64);
 return crypto.timingSafeEqual(actual,Buffer.from(digest,'hex'));
};
const validDate = value => /^\d{4}-\d{2}-\d{2}$/.test(String(value||''));
const cleanText = (value,max=500) => String(value||'').trim().slice(0,max);

function addColumn(table, col, type, def='') {
  const exists = db.prepare(`PRAGMA table_info(${table})`).all().some(x => x.name === col);
  if (!exists) db.exec(`ALTER TABLE ${table} ADD COLUMN ${col} ${type} ${def}`);
}

function audit(action, entity, entityId, details='', user='system') {
  db.prepare(`INSERT INTO audit_log(action,entity,entity_id,details,user_name,created_at) VALUES(?,?,?,?,?,datetime('now'))`).run(action, entity, entityId || null, details, user);
}

function init(){
 db.exec(`
 CREATE TABLE IF NOT EXISTS categories(id INTEGER PRIMARY KEY AUTOINCREMENT,name TEXT UNIQUE NOT NULL);
 CREATE TABLE IF NOT EXISTS products(id INTEGER PRIMARY KEY AUTOINCREMENT,name TEXT NOT NULL,category_id INTEGER,unit TEXT DEFAULT 'pcs',buy_price REAL DEFAULT 0,sell_price REAL DEFAULT 0,stock REAL DEFAULT 0,reorder_level REAL DEFAULT 0,active INTEGER DEFAULT 1,created_at TEXT DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(category_id) REFERENCES categories(id));
 CREATE TABLE IF NOT EXISTS sales(id INTEGER PRIMARY KEY AUTOINCREMENT,sale_date TEXT NOT NULL,total REAL DEFAULT 0,payment_method TEXT DEFAULT 'Cash',note TEXT,created_at TEXT DEFAULT CURRENT_TIMESTAMP);
 CREATE TABLE IF NOT EXISTS sale_items(id INTEGER PRIMARY KEY AUTOINCREMENT,sale_id INTEGER,product_id INTEGER,qty REAL,unit_price REAL,line_total REAL,FOREIGN KEY(sale_id) REFERENCES sales(id) ON DELETE CASCADE,FOREIGN KEY(product_id) REFERENCES products(id));
 CREATE TABLE IF NOT EXISTS stock_moves(id INTEGER PRIMARY KEY AUTOINCREMENT,product_id INTEGER,move_type TEXT,qty REAL,unit_cost REAL DEFAULT 0,reference TEXT,note TEXT,move_date TEXT NOT NULL,created_at TEXT DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(product_id) REFERENCES products(id));
 CREATE TABLE IF NOT EXISTS expenses(id INTEGER PRIMARY KEY AUTOINCREMENT,expense_date TEXT NOT NULL,category TEXT NOT NULL,amount REAL NOT NULL,description TEXT,created_at TEXT DEFAULT CURRENT_TIMESTAMP);
 CREATE TABLE IF NOT EXISTS settings(key TEXT PRIMARY KEY,value TEXT);
 CREATE TABLE IF NOT EXISTS users(id INTEGER PRIMARY KEY AUTOINCREMENT,username TEXT UNIQUE NOT NULL,password_hash TEXT NOT NULL,role TEXT NOT NULL,active INTEGER DEFAULT 1,created_at TEXT DEFAULT CURRENT_TIMESTAMP);
 CREATE TABLE IF NOT EXISTS sessions(token TEXT PRIMARY KEY,user_id INTEGER,created_at TEXT DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE);
 CREATE TABLE IF NOT EXISTS price_history(id INTEGER PRIMARY KEY AUTOINCREMENT,product_id INTEGER,price_type TEXT NOT NULL,price REAL NOT NULL,effective_date TEXT NOT NULL,estimated INTEGER DEFAULT 0,source_note TEXT,FOREIGN KEY(product_id) REFERENCES products(id));
 CREATE TABLE IF NOT EXISTS purchases(id INTEGER PRIMARY KEY AUTOINCREMENT,supplier TEXT,invoice_no TEXT,purchase_date TEXT NOT NULL,total REAL DEFAULT 0,note TEXT,created_at TEXT DEFAULT CURRENT_TIMESTAMP);
 CREATE TABLE IF NOT EXISTS purchase_items(id INTEGER PRIMARY KEY AUTOINCREMENT,purchase_id INTEGER,product_id INTEGER,qty REAL,buy_price REAL,line_total REAL,estimated INTEGER DEFAULT 0,FOREIGN KEY(purchase_id) REFERENCES purchases(id) ON DELETE CASCADE,FOREIGN KEY(product_id) REFERENCES products(id));
 CREATE TABLE IF NOT EXISTS daily_closings(id INTEGER PRIMARY KEY AUTOINCREMENT,close_date TEXT UNIQUE NOT NULL,opening_cash REAL DEFAULT 0,cash_sales REAL DEFAULT 0,mpesa_sales REAL DEFAULT 0,card_sales REAL DEFAULT 0,other_sales REAL DEFAULT 0,expenses REAL DEFAULT 0,expected_cash REAL DEFAULT 0,actual_cash REAL DEFAULT 0,difference REAL DEFAULT 0,closed_at TEXT,closed_by TEXT,note TEXT);
 CREATE TABLE IF NOT EXISTS audit_log(id INTEGER PRIMARY KEY AUTOINCREMENT,action TEXT,entity TEXT,entity_id INTEGER,details TEXT,user_name TEXT,created_at TEXT DEFAULT CURRENT_TIMESTAMP);
 `);
 // Compatibility migrations for earlier versions.
 addColumn('products','price_estimated_buy','INTEGER','DEFAULT 0');
 addColumn('products','price_estimated_sell','INTEGER','DEFAULT 0');
 addColumn('products','source_note','TEXT','DEFAULT \'\'');
 addColumn('stock_moves','purchase_id','INTEGER','');
 addColumn('sales','voided_at','TEXT','');
 addColumn('sales','voided_by','TEXT','');
 addColumn('sales','void_reason','TEXT','');
 addColumn('sales','location_id','INTEGER','');
 addColumn('purchases','location_id','INTEGER','');
 addColumn('expenses','location_id','INTEGER','');
 addColumn('stock_moves','location_id','INTEGER','');
 db.exec(`
 CREATE TABLE IF NOT EXISTS locations(id INTEGER PRIMARY KEY AUTOINCREMENT,name TEXT UNIQUE NOT NULL,type TEXT NOT NULL DEFAULT 'OUTLET',active INTEGER DEFAULT 1,created_at TEXT DEFAULT CURRENT_TIMESTAMP);
 CREATE TABLE IF NOT EXISTS location_stock(id INTEGER PRIMARY KEY AUTOINCREMENT,location_id INTEGER NOT NULL,product_id INTEGER NOT NULL,quantity REAL DEFAULT 0,reorder_level REAL,UNIQUE(location_id,product_id),FOREIGN KEY(location_id) REFERENCES locations(id),FOREIGN KEY(product_id) REFERENCES products(id));
 CREATE TABLE IF NOT EXISTS stock_transfers(id INTEGER PRIMARY KEY AUTOINCREMENT,from_location_id INTEGER NOT NULL,to_location_id INTEGER NOT NULL,transfer_date TEXT NOT NULL,created_by TEXT,note TEXT,created_at TEXT DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(from_location_id) REFERENCES locations(id),FOREIGN KEY(to_location_id) REFERENCES locations(id));
 CREATE TABLE IF NOT EXISTS stock_transfer_items(id INTEGER PRIMARY KEY AUTOINCREMENT,transfer_id INTEGER NOT NULL,product_id INTEGER NOT NULL,quantity REAL NOT NULL,FOREIGN KEY(transfer_id) REFERENCES stock_transfers(id) ON DELETE CASCADE,FOREIGN KEY(product_id) REFERENCES products(id));
 CREATE TABLE IF NOT EXISTS location_closings(id INTEGER PRIMARY KEY AUTOINCREMENT,location_id INTEGER NOT NULL,close_date TEXT NOT NULL,opening_cash REAL DEFAULT 0,cash_sales REAL DEFAULT 0,mpesa_sales REAL DEFAULT 0,card_sales REAL DEFAULT 0,other_sales REAL DEFAULT 0,expenses REAL DEFAULT 0,expected_cash REAL DEFAULT 0,actual_cash REAL DEFAULT 0,difference REAL DEFAULT 0,closed_at TEXT,closed_by TEXT,note TEXT,UNIQUE(location_id,close_date),FOREIGN KEY(location_id) REFERENCES locations(id));
 CREATE TABLE IF NOT EXISTS rooms(id INTEGER PRIMARY KEY AUTOINCREMENT,room_name TEXT UNIQUE NOT NULL,room_type TEXT,price_per_night REAL DEFAULT 0,status TEXT DEFAULT 'Available',active INTEGER DEFAULT 1,created_at TEXT DEFAULT CURRENT_TIMESTAMP);
 CREATE TABLE IF NOT EXISTS guests(id INTEGER PRIMARY KEY AUTOINCREMENT,name TEXT NOT NULL,phone TEXT,notes TEXT,created_at TEXT DEFAULT CURRENT_TIMESTAMP);
 CREATE TABLE IF NOT EXISTS bookings(id INTEGER PRIMARY KEY AUTOINCREMENT,guest_id INTEGER NOT NULL,room_id INTEGER NOT NULL,check_in TEXT NOT NULL,check_out TEXT NOT NULL,nights INTEGER DEFAULT 1,rate REAL DEFAULT 0,total REAL DEFAULT 0,status TEXT DEFAULT 'Reserved',payment_status TEXT DEFAULT 'Unpaid',payment_method TEXT,note TEXT,created_at TEXT DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(guest_id) REFERENCES guests(id),FOREIGN KEY(room_id) REFERENCES rooms(id));
 CREATE TABLE IF NOT EXISTS accommodation_payments(id INTEGER PRIMARY KEY AUTOINCREMENT,booking_id INTEGER NOT NULL,amount REAL NOT NULL,payment_date TEXT NOT NULL,payment_method TEXT,reference TEXT,received_by TEXT,FOREIGN KEY(booking_id) REFERENCES bookings(id));
 CREATE TABLE IF NOT EXISTS accommodation_expenses(id INTEGER PRIMARY KEY AUTOINCREMENT,expense_date TEXT NOT NULL,category TEXT NOT NULL,amount REAL NOT NULL,description TEXT,created_at TEXT DEFAULT CURRENT_TIMESTAMP);
 `);
 const addLocation=db.prepare('INSERT OR IGNORE INTO locations(name,type) VALUES(?,?)');
 [['Big Club','OUTLET'],['Small Club','OUTLET'],['Store','STORE']].forEach(x=>addLocation.run(...x));
 const bigClub=db.prepare("SELECT id FROM locations WHERE name='Big Club'").get().id;
 // Preserve the legacy global product stock as the opening balance of Big Club exactly once.
 const migrated=db.prepare("SELECT 1 FROM settings WHERE key='location_stock_migrated'").get();
 if(!migrated){const put=db.prepare('INSERT OR IGNORE INTO location_stock(location_id,product_id,quantity,reorder_level) VALUES(?,?,?,?)'); for(const p of db.prepare('SELECT id,stock,reorder_level FROM products').all()) put.run(bigClub,p.id,p.stock,p.reorder_level); db.prepare('INSERT INTO settings(key,value) VALUES(?,?)').run('location_stock_migrated',today());}
 // Historical records belonged to the original Big Club operation.
 for(const table of ['sales','purchases','expenses','stock_moves']) db.prepare(`UPDATE ${table} SET location_id=? WHERE location_id IS NULL`).run(bigClub);

 const cats=['Beer','Spirits','Soft Drinks','Water','Food','Cans','Other'];
 const addCat=db.prepare('INSERT OR IGNORE INTO categories(name) VALUES(?)'); cats.forEach(name=>addCat.run(name));
 if(!db.prepare('SELECT 1 FROM users LIMIT 1').get()) db.prepare('INSERT INTO users(username,password_hash,role) VALUES(?,?,?)').run('admin',hashPassword('admin123'),'Administrator/Owner');
 if(!db.prepare('SELECT 1 FROM settings WHERE key=?').get('business_name')) db.prepare('INSERT INTO settings(key,value) VALUES(?,?)').run('business_name','Park Bar & Accommodation');
 seedProducts();
}

