init();

const getLocation = id => db.prepare('SELECT * FROM locations WHERE id=? AND active=1').get(Number(id)) || db.prepare("SELECT * FROM locations WHERE name='Big Club'").get();
const stockAt = (locationId, productId) => db.prepare('SELECT quantity,reorder_level FROM location_stock WHERE location_id=? AND product_id=?').get(locationId,productId) || {quantity:0,reorder_level:null};
const ensureStock = (locationId, productId) => db.prepare('INSERT OR IGNORE INTO location_stock(location_id,product_id,quantity,reorder_level) SELECT ?,id,0,reorder_level FROM products WHERE id=?').run(locationId,productId);
const changeStock = (locationId, productId, delta) => { ensureStock(locationId,productId); const row=stockAt(locationId,productId); if(row.quantity+delta<0) throw Error(`Not enough stock. Available: ${row.quantity}`); db.prepare('UPDATE location_stock SET quantity=quantity+? WHERE location_id=? AND product_id=?').run(delta,locationId,productId); };
const locFilter = (column, locationId, params) => { if(locationId && locationId!=='all'){params.push(Number(locationId)); return ` AND ${column}=?`; } return ''; };

function auth(req,res,next){ const token=req.headers.authorization?.replace('Bearer ',''); if(!token) return res.status(401).json({error:'Login required'}); const s=db.prepare('SELECT u.* FROM sessions s JOIN users u ON u.id=s.user_id WHERE s.token=? AND u.active=1').get(token); if(!s) return res.status(401).json({error:'Session expired'}); req.user=s; next(); }
const allow=(...roles)=>(req,res,next)=>roles.includes(req.user.role)?next():res.status(403).json({error:'Permission denied'});

app.post('/api/login',(req,res)=>{try{const {username,password}=req.body||{};const u=db.prepare('SELECT * FROM users WHERE username=? AND active=1').get(cleanText(username,60));if(!u||!password||!verifyPassword(password,u.password_hash))return res.status(401).json({error:'Invalid username or password'});if(!u.password_hash.startsWith('scrypt$'))db.prepare('UPDATE users SET password_hash=? WHERE id=?').run(hashPassword(password),u.id);const token=crypto.randomBytes(32).toString('hex');db.prepare('INSERT INTO sessions(token,user_id) VALUES(?,?)').run(token,u.id);res.json({token,user:{id:u.id,username:u.username,role:u.role}})}catch(e){res.status(400).json({error:'Could not sign in'})}});
app.get('/api/me',auth,(req,res)=>res.json({id:req.user.id,username:req.user.username,role:req.user.role}));
app.post('/api/logout',auth,(req,res)=>{db.prepare('DELETE FROM sessions WHERE user_id=?').run(req.user.id);res.json({ok:true})});
app.get('/api/users',auth,allow('Administrator/Owner'),(req,res)=>res.json(db.prepare('SELECT id,username,role,active,created_at FROM users ORDER BY username').all()));
app.post('/api/users',auth,allow('Administrator/Owner'),(req,res)=>{try{const x=req.body||{},username=cleanText(x.username,60),password=String(x.password||'');const roles=['Administrator/Owner','Manager','Cashier','Stock clerk'];if(!/^[a-zA-Z0-9._-]{3,60}$/.test(username))throw Error('Username must be 3–60 letters, numbers, dots, dashes or underscores');if(password.length<8)throw Error('Password must be at least 8 characters');if(!roles.includes(x.role))throw Error('Choose a valid role');const r=db.prepare('INSERT INTO users(username,password_hash,role) VALUES(?,?,?)').run(username,hashPassword(password),x.role);audit('CREATE','user',r.lastInsertRowid,`${username} (${x.role})`,req.user.username);res.json({id:r.lastInsertRowid})}catch(e){res.status(400).json({error:e.message})}});
app.put('/api/users/:id',auth,allow('Administrator/Owner'),(req,res)=>{try{const x=req.body||{},id=Number(req.params.id),u=db.prepare('SELECT * FROM users WHERE id=?').get(id);if(!u)throw Error('User not found');if(id===req.user.id&&x.active===false)throw Error('You cannot deactivate your own account');if(x.role&&!['Administrator/Owner','Manager','Cashier','Stock clerk'].includes(x.role))throw Error('Choose a valid role');if(x.password&&String(x.password).length<8)throw Error('Password must be at least 8 characters');db.prepare('UPDATE users SET role=?,active=?,password_hash=? WHERE id=?').run(x.role||u.role,x.active===false?0:1,x.password?hashPassword(x.password):u.password_hash,id);if(x.password||x.active===false)db.prepare('DELETE FROM sessions WHERE user_id=?').run(id);audit('UPDATE','user',id,`${u.username} updated`,req.user.username);res.json({ok:true})}catch(e){res.status(400).json({error:e.message})}});

app.get('/api/locations',auth,(req,res)=>res.json(db.prepare('SELECT * FROM locations WHERE active=1 ORDER BY CASE name WHEN \'Big Club\' THEN 0 WHEN \'Small Club\' THEN 1 WHEN \'Store\' THEN 2 ELSE 3 END,name').all()));
app.post('/api/locations',auth,allow('Administrator/Owner','Manager'),(req,res)=>{try{const x=req.body||{},name=cleanText(x.name,80),type=['OUTLET','STORE','COUNTER'].includes(x.type)?x.type:'OUTLET';if(!name)throw Error('Location name is required');const r=db.prepare('INSERT INTO locations(name,type) VALUES(?,?)').run(name,type);audit('CREATE','location',r.lastInsertRowid,`${name} (${type})`,req.user.username);res.json({id:r.lastInsertRowid})}catch(e){res.status(400).json({error:e.message})}});
app.post('/api/purchases',auth,allow('Administrator/Owner','Manager','Stock clerk'),(req,res)=>{try{const x=req.body||{},loc=getLocation(x.location_id);if(!Array.isArray(x.items)||!x.items.length)throw Error('Add at least one item');const out=db.transaction(()=>{const purchase=db.prepare('INSERT INTO purchases(supplier,invoice_no,purchase_date,total,note,location_id) VALUES(?,?,?,?,?,?)').run(cleanText(x.supplier,120),cleanText(x.invoice_no,120),x.purchase_date||today(),0,cleanText(x.note,500),loc.id);let total=0;for(const i of x.items){const p=db.prepare('SELECT * FROM products WHERE id=? AND active=1').get(i.product_id),q=num(i.qty),price=num(i.buy_price);if(!p||q<=0||price<0)throw Error('Invalid purchase line');total+=q*price;db.prepare('INSERT INTO purchase_items(purchase_id,product_id,qty,buy_price,line_total,estimated) VALUES(?,?,?,?,?,?)').run(purchase.lastInsertRowid,p.id,q,price,q*price,i.estimated?1:0);changeStock(loc.id,p.id,q);db.prepare('UPDATE products SET buy_price=?,price_estimated_buy=?,source_note=? WHERE id=?').run(price,i.estimated?1:0,i.estimated?'Purchase price marked estimated':'Purchase recorded',p.id);db.prepare('INSERT INTO stock_moves(product_id,location_id,move_type,qty,unit_cost,reference,note,move_date,purchase_id) VALUES(?,?,?,?,?,?,?,?,?)').run(p.id,loc.id,'IN',q,price,`Purchase #${purchase.lastInsertRowid}`,`Supplier: ${x.supplier||''}`,x.purchase_date||today(),purchase.lastInsertRowid);db.prepare('INSERT INTO price_history(product_id,price_type,price,effective_date,estimated,source_note) VALUES(?,?,?,?,?,?)').run(p.id,'BUY',price,x.purchase_date||today(),i.estimated?1:0,'Purchase record')}db.prepare('UPDATE purchases SET total=? WHERE id=?').run(total,purchase.lastInsertRowid);return{id:purchase.lastInsertRowid,total}})();audit('CREATE','purchase',out.id,`${loc.name}: Purchase ${out.total}`,req.user.username);res.json(out)}catch(e){res.status(400).json({error:e.message})}});
app.post('/api/expenses',auth,allow('Administrator/Owner','Manager'),(req,res)=>{try{const x=req.body||{},loc=getLocation(x.location_id);if(num(x.amount)<=0)throw Error('Amount must be greater than zero');const r=db.prepare('INSERT INTO expenses(expense_date,category,amount,description,location_id) VALUES(?,?,?,?,?)').run(x.expense_date||today(),cleanText(x.category,80)||'Other',num(x.amount),cleanText(x.description,500),loc.id);audit('CREATE','expense',r.lastInsertRowid,`${loc.name}: ${x.category} ${x.amount}`,req.user.username);res.json({id:r.lastInsertRowid})}catch(e){res.status(400).json({error:e.message})}});
app.post('/api/closing',auth,allow('Administrator/Owner','Manager'),(req,res)=>{try{const x=req.body||{},loc=getLocation(x.location_id),d=x.close_date||today();if(!validDate(d))throw Error('Enter a valid closing date');const by=Object.fromEntries(db.prepare('SELECT payment_method,COALESCE(SUM(total),0) total FROM sales WHERE sale_date=? AND location_id=? AND voided_at IS NULL GROUP BY payment_method').all(d,loc.id).map(r=>[r.payment_method,r.total])),exp=db.prepare('SELECT COALESCE(SUM(amount),0) total FROM expenses WHERE expense_date=? AND location_id=?').get(d,loc.id).total,expected=num(x.opening_cash)+num(by.Cash)-num(exp),actual=num(x.actual_cash),diff=actual-expected;db.prepare(`INSERT INTO location_closings(location_id,close_date,opening_cash,cash_sales,mpesa_sales,card_sales,other_sales,expenses,expected_cash,actual_cash,difference,closed_at,closed_by,note) VALUES(?,?,?,?,?,?,?,?,?,?,?,datetime('now'),?,?) ON CONFLICT(location_id,close_date) DO UPDATE SET opening_cash=excluded.opening_cash,cash_sales=excluded.cash_sales,mpesa_sales=excluded.mpesa_sales,card_sales=excluded.card_sales,other_sales=excluded.other_sales,expenses=excluded.expenses,expected_cash=excluded.expected_cash,actual_cash=excluded.actual_cash,difference=excluded.difference,closed_at=excluded.closed_at,closed_by=excluded.closed_by,note=excluded.note`).run(loc.id,d,num(x.opening_cash),by.Cash||0,by['M-Pesa']||0,by.Card||0,by.Other||0,exp,expected,actual,diff,req.user.username,cleanText(x.note,500));audit('CLOSE','daily_closing',loc.id,`${loc.name} ${d}: difference ${diff}`,req.user.username);res.json({date:d,expected_cash:expected,actual_cash:actual,difference:diff})}catch(e){res.status(400).json({error:e.message})}});
app.get('/api/closing',auth,(req,res)=>{const d=req.query.date||today(),loc=getLocation(req.query.location_id),closed=db.prepare('SELECT * FROM location_closings WHERE close_date=? AND location_id=?').get(d,loc.id),opening=closed?.opening_cash||0,by=Object.fromEntries(db.prepare('SELECT payment_method,COALESCE(SUM(total),0) total FROM sales WHERE sale_date=? AND location_id=? AND voided_at IS NULL GROUP BY payment_method').all(d,loc.id).map(r=>[r.payment_method,r.total])),exp=db.prepare('SELECT COALESCE(SUM(amount),0) total FROM expenses WHERE expense_date=? AND location_id=?').get(d,loc.id).total;res.json({date:d,opening_cash:opening,cash_sales:by.Cash||0,mpesa_sales:by['M-Pesa']||0,card_sales:by.Card||0,other_sales:by.Other||0,expenses:exp,expected_cash:num(opening)+num(by.Cash)-num(exp),closing:closed||null})});
app.get('/api/reports',auth,(req,res)=>{const from=req.query.from||today(),to=req.query.to||today(),loc=req.query.location_id&&req.query.location_id!=='all'?getLocation(req.query.location_id):null,lf=loc?' AND location_id=?':'',args=loc?[from,to,loc.id]:[from,to],sales=db.prepare(`SELECT COALESCE(SUM(total),0) total,COUNT(*) count FROM sales WHERE sale_date BETWEEN ? AND ? AND voided_at IS NULL${lf}`).get(...args),expenses=db.prepare(`SELECT COALESCE(SUM(amount),0) total FROM expenses WHERE expense_date BETWEEN ? AND ?${lf}`).get(...args),products=loc?db.prepare(`SELECT p.id,p.name,p.unit,COALESCE(ls.quantity,0) stock,p.buy_price,p.sell_price,p.price_estimated_buy,p.price_estimated_sell,COALESCE(SUM(CASE WHEN sm.move_type='SALE' AND sm.move_date BETWEEN ? AND ? THEN sm.qty ELSE 0 END),0) sold,COALESCE(SUM(CASE WHEN sm.move_type IN ('IN','OPENING','TRANSFER_IN') AND sm.move_date BETWEEN ? AND ? THEN sm.qty ELSE 0 END),0) received FROM products p LEFT JOIN location_stock ls ON ls.product_id=p.id AND ls.location_id=? LEFT JOIN stock_moves sm ON sm.product_id=p.id AND sm.location_id=? WHERE p.active=1 GROUP BY p.id ORDER BY sold DESC`).all(from,to,from,to,loc.id,loc.id):db.prepare(`SELECT p.id,p.name,p.unit,COALESCE(SUM(ls.quantity),0) stock,p.buy_price,p.sell_price,p.price_estimated_buy,p.price_estimated_sell,0 sold,0 received FROM products p LEFT JOIN location_stock ls ON ls.product_id=p.id WHERE p.active=1 GROUP BY p.id`).all(),byDay=db.prepare(`SELECT sale_date date,ROUND(SUM(total),2) sales FROM sales WHERE sale_date BETWEEN ? AND ? AND voided_at IS NULL${lf} GROUP BY sale_date ORDER BY sale_date`).all(...args),byPay=db.prepare(`SELECT payment_method,ROUND(SUM(total),2) total FROM sales WHERE sale_date BETWEEN ? AND ? AND voided_at IS NULL${lf} GROUP BY payment_method`).all(...args),byExpense=db.prepare(`SELECT category,ROUND(SUM(amount),2) total FROM expenses WHERE expense_date BETWEEN ? AND ?${lf} GROUP BY category ORDER BY total DESC`).all(...args);res.json({from,to,location:loc?.name||'All Locations',sales,expenses,cogs:0,gross_profit:sales.total,profit:sales.total-expenses.total,products,byDay,byPay,byExpense})});
app.get('/api/dashboard',auth,(req,res)=>{
 const d=req.query.date||today();
 const locationId=req.query.location_id, args=[d],sf=locFilter('location_id',locationId,args),sales=db.prepare(`SELECT COALESCE(SUM(total),0) total,COUNT(*) count FROM sales WHERE sale_date=? AND voided_at IS NULL${sf}`).get(...args);
 const ea=[d],ef=locFilter('location_id',locationId,ea),exp=db.prepare(`SELECT COALESCE(SUM(amount),0) total FROM expenses WHERE expense_date=?${ef}`).get(...ea);
 const stock=locationId&&locationId!=='all'?db.prepare(`SELECT COALESCE(SUM(ls.quantity*p.buy_price),0) value,COUNT(p.id) products,SUM(CASE WHEN ls.quantity<=COALESCE(ls.reorder_level,p.reorder_level) THEN 1 ELSE 0 END) low FROM products p LEFT JOIN location_stock ls ON ls.product_id=p.id AND ls.location_id=? WHERE p.active=1`).get(locationId):db.prepare('SELECT COALESCE(SUM(quantity*p.buy_price),0) value,COUNT(DISTINCT product_id) products,SUM(CASE WHEN quantity<=COALESCE(reorder_level,0) THEN 1 ELSE 0 END) low FROM location_stock JOIN products p ON p.id=product_id WHERE p.active=1').get();
 const ta=[d],tf=locFilter('s.location_id',locationId,ta),top=db.prepare(`SELECT p.name,SUM(si.qty) qty,SUM(si.line_total) revenue FROM sale_items si JOIN sales s ON s.id=si.sale_id JOIN products p ON p.id=si.product_id WHERE s.sale_date=? AND s.voided_at IS NULL${tf} GROUP BY p.id ORDER BY revenue DESC LIMIT 5`).all(...ta);
 const trend=db.prepare(`WITH RECURSIVE days(d) AS (SELECT date(?) UNION ALL SELECT date(d,'-1 day') FROM days WHERE d>date(?,'-6 day')) SELECT d date,COALESCE((SELECT SUM(total) FROM sales WHERE sale_date=d AND voided_at IS NULL${locationId&&locationId!=='all'?' AND location_id='+Number(locationId):''}),0) sales FROM days ORDER BY d`).all(d,d);
 const closing=locationId&&locationId!=='all'?db.prepare('SELECT * FROM location_closings WHERE close_date=? AND location_id=?').get(d,locationId):null;
 res.json({date:d,sales,expenses:exp,profit:sales.total-exp.total,stock,top,trend,closing});
});

app.get('/api/products',auth,(req,res)=>{const l=req.query.location_id;if(l&&l!=='all')return res.json(db.prepare(`SELECT p.*,c.name category,COALESCE(ls.quantity,0) stock,COALESCE(ls.reorder_level,p.reorder_level) reorder_level FROM products p LEFT JOIN categories c ON c.id=p.category_id LEFT JOIN location_stock ls ON ls.product_id=p.id AND ls.location_id=? WHERE p.active=1 ORDER BY c.name,p.name`).all(l));res.json(db.prepare(`SELECT p.*,c.name category,COALESCE(SUM(ls.quantity),0) stock FROM products p LEFT JOIN categories c ON c.id=p.category_id LEFT JOIN location_stock ls ON ls.product_id=p.id WHERE p.active=1 GROUP BY p.id ORDER BY c.name,p.name`).all())});
app.get('/api/products/:id/insights',auth,(req,res)=>{const id=req.params.id;const p=db.prepare(`SELECT p.*,c.name category FROM products p LEFT JOIN categories c ON c.id=p.category_id WHERE p.id=?`).get(id);if(!p)return res.status(404).json({error:'Product not found'});const sold=db.prepare(`SELECT COALESCE(SUM(si.qty),0) qty,COALESCE(SUM(si.line_total),0) revenue FROM sale_items si JOIN sales s ON s.id=si.sale_id WHERE si.product_id=? AND s.sale_date>=date(?,'-6 day') AND s.sale_date<=?`).get(id,today(),today());const prev=db.prepare(`SELECT COALESCE(SUM(si.qty),0) qty FROM sale_items si JOIN sales s ON s.id=si.sale_id WHERE si.product_id=? AND s.sale_date>=date(?,'-13 day') AND s.sale_date<=date(?,'-7 day')`).get(id,today(),today());const trendPct=prev.qty?((sold.qty-prev.qty)/prev.qty*100):null;const hist=db.prepare('SELECT * FROM price_history WHERE product_id=? ORDER BY effective_date DESC,id DESC').all(id);const daily=db.prepare(`WITH RECURSIVE days(d) AS (SELECT date(?) UNION ALL SELECT date(d,'-1 day') FROM days WHERE d>date(?,'-6 day')) SELECT d date,COALESCE((SELECT SUM(si.qty) FROM sale_items si JOIN sales s ON s.id=si.sale_id WHERE si.product_id=? AND s.sale_date=d),0) qty FROM days ORDER BY d`).all(today(),today(),id);res.json({product:p,sold,previous_qty:prev.qty,trend_pct:trendPct,margin:p.sell_price-p.buy_price,margin_pct:p.sell_price?((p.sell_price-p.buy_price)/p.sell_price*100):0,history:hist,daily,reorder:p.stock<=p.reorder_level});});
app.post('/api/products',auth,allow('Administrator/Owner','Manager'),(req,res)=>{try{const x=req.body;if(!x.name)throw Error('Product name is required');const estimated=!!x.price_estimated;const r=db.prepare(`INSERT INTO products(name,category_id,unit,buy_price,sell_price,stock,reorder_level,price_estimated_buy,price_estimated_sell,source_note) VALUES(?,?,?,?,?,?,?,?,?,?)`).run(x.name,x.category_id||null,x.unit||'pcs',num(x.buy_price),num(x.sell_price),num(x.stock),num(x.reorder_level),estimated?1:0,estimated?1:0,x.source_note||'');if(num(x.stock))db.prepare(`INSERT INTO stock_moves(product_id,move_type,qty,unit_cost,reference,move_date,note) VALUES(?,?,?,?,?,?,?)`).run(r.lastInsertRowid,'OPENING',num(x.stock),num(x.buy_price),'Opening stock',today(),'Manual opening stock');audit('CREATE','product',r.lastInsertRowid,x.name,req.user.username);res.json({id:r.lastInsertRowid})}catch(e){res.status(400).json({error:e.message})}});
app.put('/api/products/:id',auth,allow('Administrator/Owner','Manager'),(req,res)=>{try{const x=req.body;const old=db.prepare('SELECT * FROM products WHERE id=?').get(req.params.id);db.prepare(`UPDATE products SET name=?,category_id=?,unit=?,buy_price=?,sell_price=?,reorder_level=?,price_estimated_buy=?,price_estimated_sell=?,source_note=? WHERE id=?`).run(x.name,x.category_id||null,x.unit||'pcs',num(x.buy_price),num(x.sell_price),num(x.reorder_level),x.price_estimated_buy?1:0,x.price_estimated_sell?1:0,x.source_note||'',req.params.id);if(old&&old.buy_price!==num(x.buy_price))db.prepare(`INSERT INTO price_history(product_id,price_type,price,effective_date,estimated,source_note) VALUES(?,?,?,?,?,?)`).run(req.params.id,'BUY',num(x.buy_price),today(),x.price_estimated_buy?1:0,'Product price update');if(old&&old.sell_price!==num(x.sell_price))db.prepare(`INSERT INTO price_history(product_id,price_type,price,effective_date,estimated,source_note) VALUES(?,?,?,?,?,?)`).run(req.params.id,'SELL',num(x.sell_price),today(),x.price_estimated_sell?1:0,'Product price update');audit('UPDATE','product',req.params.id,x.name,req.user.username);res.json({ok:true})}catch(e){res.status(400).json({error:e.message})}});
app.delete('/api/products/:id',auth,allow('Administrator/Owner','Manager'),(req,res)=>{db.prepare('UPDATE products SET active=0 WHERE id=?').run(req.params.id);audit('ARCHIVE','product',req.params.id,'',req.user.username);res.json({ok:true})});
app.get('/api/categories',auth,(req,res)=>res.json(db.prepare('SELECT * FROM categories ORDER BY name').all()));

app.post('/api/stock',auth,allow('Administrator/Owner','Manager','Stock clerk'),(req,res)=>{try{const x=req.body||{},qty=num(x.qty),type=String(x.move_type||''),loc=getLocation(x.location_id);if(!['IN','OUT','ADJUSTMENT_IN','ADJUSTMENT_OUT'].includes(type)||qty<=0)throw Error('Enter a valid positive stock movement');if(type.startsWith('ADJUSTMENT')&&!cleanText(x.reason,120))throw Error('A reason is required for stock corrections');const p=db.prepare('SELECT * FROM products WHERE id=? AND active=1').get(x.product_id);if(!p)throw Error('Product not found');const delta=['OUT','ADJUSTMENT_OUT'].includes(type)?-qty:qty;const note=[cleanText(x.reason,120),cleanText(x.note,400)].filter(Boolean).join(' — ');db.transaction(()=>{changeStock(loc.id,p.id,delta);db.prepare('INSERT INTO stock_moves(product_id,location_id,move_type,qty,unit_cost,reference,note,move_date) VALUES(?,?,?,?,?,?,?,?)').run(p.id,loc.id,type,qty,num(x.unit_cost||p.buy_price),cleanText(x.reference,120),note,x.move_date||today())})();audit('STOCK_'+type,'stock',p.id,`${loc.name}: ${p.name} qty ${qty}; ${note}`,req.user.username);res.json({ok:true})}catch(e){res.status(400).json({error:e.message})}});
app.post('/api/stock/count',auth,allow('Administrator/Owner','Manager','Stock clerk'),(req,res)=>{try{const x=req.body||{},loc=getLocation(x.location_id),p=db.prepare('SELECT * FROM products WHERE id=? AND active=1').get(x.product_id),counted=num(x.quantity),reason=cleanText(x.reason,160);if(!p||counted<0)throw Error('Enter a valid product and counted quantity');if(!reason)throw Error('A reason is required when setting stock');const current=stockAt(loc.id,p.id).quantity,delta=counted-current,type=delta>=0?'ADJUSTMENT_IN':'ADJUSTMENT_OUT';db.transaction(()=>{changeStock(loc.id,p.id,delta);db.prepare('INSERT INTO stock_moves(product_id,location_id,move_type,qty,unit_cost,reference,note,move_date) VALUES(?,?,?,?,?,?,?,?)').run(p.id,loc.id,type,Math.abs(delta),p.buy_price,'Physical count',reason,x.move_date||today())})();audit('SET_STOCK','stock',p.id,`${loc.name}: ${p.name} ${current} → ${counted}; ${reason}`,req.user.username);res.json({ok:true,previous:current,quantity:counted})}catch(e){res.status(400).json({error:e.message})}});
app.get('/api/stock/moves',auth,(req,res)=>res.json(db.prepare(`SELECT m.*,p.name product,p.unit FROM stock_moves m JOIN products p ON p.id=m.product_id ORDER BY m.move_date DESC,m.id DESC LIMIT 300`).all()));

app.post('/api/sales',auth,allow('Administrator/Owner','Manager','Cashier'),(req,res)=>{try{const x=req.body||{},loc=getLocation(x.location_id);if(!Array.isArray(x.items)||!x.items.length)throw Error('Add at least one item');const out=db.transaction(()=>{let total=0,checked=[];for(const i of x.items){const p=db.prepare('SELECT * FROM products WHERE id=? AND active=1').get(i.product_id),q=num(i.qty),available=stockAt(loc.id,i.product_id).quantity;if(!p||q<=0)throw Error('Invalid sale item');if(available<q)throw Error(`Not enough ${p.name}. Available: ${available}`);const price=num(i.unit_price||p.sell_price);total+=q*price;checked.push({p,q,price})}const s=db.prepare('INSERT INTO sales(sale_date,total,payment_method,note,location_id) VALUES(?,?,?,?,?)').run(x.sale_date||today(),total,x.payment_method||'Cash',x.note||'',loc.id);for(const z of checked){db.prepare('INSERT INTO sale_items(sale_id,product_id,qty,unit_price,line_total) VALUES(?,?,?,?,?)').run(s.lastInsertRowid,z.p.id,z.q,z.price,z.q*z.price);changeStock(loc.id,z.p.id,-z.q);db.prepare('INSERT INTO stock_moves(product_id,location_id,move_type,qty,unit_cost,reference,move_date,note) VALUES(?,?,?,?,?,?,?,?)').run(z.p.id,loc.id,'SALE',z.q,z.p.buy_price,`Sale #${s.lastInsertRowid}`,x.sale_date||today(),'Automatic stock deduction')}return{id:s.lastInsertRowid,total}})();audit('CREATE','sale',out.id,`${loc.name}: Sale ${out.total}`,req.user.username);res.json(out)}catch(e){res.status(400).json({error:e.message})}});
app.get('/api/sales',auth,(req,res)=>{const from=req.query.from||today(),to=req.query.to||today();res.json(db.prepare(`SELECT s.*,GROUP_CONCAT(p.name||' x'||si.qty, ', ') items FROM sales s LEFT JOIN sale_items si ON si.sale_id=s.id LEFT JOIN products p ON p.id=si.product_id WHERE s.sale_date BETWEEN ? AND ? GROUP BY s.id ORDER BY s.sale_date DESC,s.id DESC`).all(from,to))});
app.post('/api/sales/:id/void',auth,allow('Administrator/Owner','Manager'),(req,res)=>{try{const id=Number(req.params.id),reason=cleanText(req.body?.reason,250),sale=db.prepare('SELECT * FROM sales WHERE id=?').get(id);if(!reason||!sale||sale.voided_at)throw Error(!reason?'A void reason is required':'Sale cannot be voided');db.transaction(()=>{for(const item of db.prepare('SELECT si.*,p.buy_price FROM sale_items si JOIN products p ON p.id=si.product_id WHERE si.sale_id=?').all(id)){changeStock(sale.location_id,item.product_id,item.qty);db.prepare('INSERT INTO stock_moves(product_id,location_id,move_type,qty,unit_cost,reference,note,move_date) VALUES(?,?,?,?,?,?,?,?)').run(item.product_id,sale.location_id,'VOID',item.qty,item.buy_price,`Void sale #${id}`,reason,today())}db.prepare("UPDATE sales SET voided_at=datetime('now'),voided_by=?,void_reason=? WHERE id=?").run(req.user.username,reason,id)})();audit('VOID','sale',id,reason,req.user.username);res.json({ok:true})}catch(e){res.status(400).json({error:e.message})}});

app.post('/api/expenses',auth,allow('Administrator/Owner','Manager'),(req,res)=>{try{const x=req.body;if(num(x.amount)<=0)throw Error('Amount must be greater than zero');const r=db.prepare('INSERT INTO expenses(expense_date,category,amount,description) VALUES(?,?,?,?)').run(x.expense_date||today(),x.category||'Other',num(x.amount),x.description||'');audit('CREATE','expense',r.lastInsertRowid,`${x.category} ${x.amount}`,req.user.username);res.json({id:r.lastInsertRowid})}catch(e){res.status(400).json({error:e.message})}});
app.get('/api/expenses',auth,(req,res)=>{const from=req.query.from||today(),to=req.query.to||today();res.json(db.prepare('SELECT * FROM expenses WHERE expense_date BETWEEN ? AND ? ORDER BY expense_date DESC,id DESC').all(from,to))});

app.post('/api/purchases',auth,allow('Administrator/Owner','Manager','Stock clerk'),(req,res)=>{try{const x=req.body;if(!Array.isArray(x.items)||!x.items.length)throw Error('Add at least one item');const tx=db.transaction(()=>{let total=0;const p=db.prepare('INSERT INTO purchases(supplier,invoice_no,purchase_date,total,note) VALUES(?,?,?,?,?)');const purchase=p.run(x.supplier||'',x.invoice_no||'',x.purchase_date||today(),0,x.note||'');const item=db.prepare('INSERT INTO purchase_items(purchase_id,product_id,qty,buy_price,line_total,estimated) VALUES(?,?,?,?,?,?)');const move=db.prepare(`INSERT INTO stock_moves(product_id,move_type,qty,unit_cost,reference,note,move_date,purchase_id) VALUES(?,?,?,?,?,?,?,?)`);for(const i of x.items){const product=db.prepare('SELECT * FROM products WHERE id=?').get(i.product_id);if(!product)throw Error('Invalid product');const q=num(i.qty),price=num(i.buy_price);if(q<=0||price<0)throw Error('Invalid purchase line');total+=q*price;item.run(purchase.lastInsertRowid,product.id,q,price,q*price,i.estimated?1:0);db.prepare('UPDATE products SET stock=stock+?,buy_price=?,price_estimated_buy=?,source_note=? WHERE id=?').run(q,price,i.estimated?1:0,i.estimated?'Purchase price marked estimated':'Purchase recorded',product.id);move.run(product.id,'IN',q,price,`Purchase #${purchase.lastInsertRowid}`,`Supplier: ${x.supplier||''}`,x.purchase_date||today(),purchase.lastInsertRowid);db.prepare(`INSERT INTO price_history(product_id,price_type,price,effective_date,estimated,source_note) VALUES(?,?,?,?,?,?)`).run(product.id,'BUY',price,x.purchase_date||today(),i.estimated?1:0,'Purchase record')}db.prepare('UPDATE purchases SET total=? WHERE id=?').run(total,purchase.lastInsertRowid);return{id:purchase.lastInsertRowid,total}});const out=tx();audit('CREATE','purchase',out.id,`Purchase ${out.total}`,req.user.username);res.json(out)}catch(e){res.status(400).json({error:e.message})}});
app.get('/api/purchases',auth,(req,res)=>res.json(db.prepare(`SELECT p.*,COALESCE(GROUP_CONCAT(pr.name||' x'||pi.qty,'; '),'') items FROM purchases p LEFT JOIN purchase_items pi ON pi.purchase_id=p.id LEFT JOIN products pr ON pr.id=pi.product_id GROUP BY p.id ORDER BY p.purchase_date DESC,p.id DESC LIMIT 300`).all()));

app.post('/api/transfers',auth,allow('Administrator/Owner','Manager','Stock clerk'),(req,res)=>{try{const x=req.body||{},from=getLocation(x.from_location_id),to=getLocation(x.to_location_id),items=x.items;if(from.id===to.id)throw Error('Choose different source and destination');if(!Array.isArray(items)||!items.length)throw Error('Add at least one transfer item');const out=db.transaction(()=>{const t=db.prepare('INSERT INTO stock_transfers(from_location_id,to_location_id,transfer_date,created_by,note) VALUES(?,?,?,?,?)').run(from.id,to.id,x.transfer_date||today(),req.user.username,cleanText(x.note,500));for(const i of items){const q=num(i.quantity),p=db.prepare('SELECT * FROM products WHERE id=? AND active=1').get(i.product_id);if(!p||q<=0)throw Error('Invalid transfer item');if(stockAt(from.id,p.id).quantity<q)throw Error(`Not enough ${p.name} in ${from.name}`);changeStock(from.id,p.id,-q);changeStock(to.id,p.id,q);db.prepare('INSERT INTO stock_transfer_items(transfer_id,product_id,quantity) VALUES(?,?,?)').run(t.lastInsertRowid,p.id,q);const move=db.prepare('INSERT INTO stock_moves(product_id,location_id,move_type,qty,unit_cost,reference,note,move_date) VALUES(?,?,?,?,?,?,?,?)');move.run(p.id,from.id,'TRANSFER_OUT',q,p.buy_price,`Transfer #${t.lastInsertRowid}`,`To ${to.name}`,x.transfer_date||today());move.run(p.id,to.id,'TRANSFER_IN',q,p.buy_price,`Transfer #${t.lastInsertRowid}`,`From ${from.name}`,x.transfer_date||today())}return {id:t.lastInsertRowid}})();audit('TRANSFER','stock_transfer',out.id,`${from.name} → ${to.name}`,req.user.username);res.json(out)}catch(e){res.status(400).json({error:e.message})}});
app.get('/api/transfers',auth,(req,res)=>res.json(db.prepare(`SELECT t.*,f.name from_location,d.name to_location,GROUP_CONCAT(p.name||' x'||i.quantity,'; ') items FROM stock_transfers t JOIN locations f ON f.id=t.from_location_id JOIN locations d ON d.id=t.to_location_id LEFT JOIN stock_transfer_items i ON i.transfer_id=t.id LEFT JOIN products p ON p.id=i.product_id GROUP BY t.id ORDER BY t.transfer_date DESC,t.id DESC LIMIT 300`).all()));

app.get('/api/accommodation/dashboard',auth,(req,res)=>{const d=today(),rooms=db.prepare("SELECT SUM(status='Occupied') occupied,SUM(status='Available') available FROM rooms WHERE active=1").get(),checkins=db.prepare('SELECT COUNT(*) n FROM bookings WHERE check_in=?').get(d).n,checkouts=db.prepare('SELECT COUNT(*) n FROM bookings WHERE check_out=?').get(d).n,revenue=db.prepare('SELECT COALESCE(SUM(amount),0) total FROM accommodation_payments WHERE payment_date=?').get(d).total,outstanding=db.prepare(`SELECT COALESCE(SUM(b.total-COALESCE(p.paid,0)),0) total FROM bookings b LEFT JOIN (SELECT booking_id,SUM(amount) paid FROM accommodation_payments GROUP BY booking_id) p ON p.booking_id=b.id WHERE b.status NOT IN ('Cancelled')`).get().total;res.json({rooms,checkins,checkouts,revenue,outstanding})});
app.get('/api/rooms',auth,(req,res)=>res.json(db.prepare('SELECT * FROM rooms WHERE active=1 ORDER BY room_name').all()));
app.post('/api/rooms',auth,allow('Administrator/Owner','Manager'),(req,res)=>{try{const x=req.body||{};if(!cleanText(x.room_name,60))throw Error('Room name is required');const r=db.prepare('INSERT INTO rooms(room_name,room_type,price_per_night,status) VALUES(?,?,?,?)').run(cleanText(x.room_name,60),cleanText(x.room_type,60),num(x.price_per_night),x.status||'Available');audit('CREATE','room',r.lastInsertRowid,x.room_name,req.user.username);res.json({id:r.lastInsertRowid})}catch(e){res.status(400).json({error:e.message})}});
app.get('/api/bookings',auth,(req,res)=>res.json(db.prepare('SELECT b.*,g.name guest,g.phone,r.room_name FROM bookings b JOIN guests g ON g.id=b.guest_id JOIN rooms r ON r.id=b.room_id ORDER BY b.check_in DESC,b.id DESC').all()));
app.post('/api/bookings',auth,allow('Administrator/Owner','Manager'),(req,res)=>{try{const x=req.body||{},checkIn=x.check_in,checkOut=x.check_out;if(!cleanText(x.guest_name,100)||!validDate(checkIn)||!validDate(checkOut)||checkOut<=checkIn)throw Error('Guest, valid check-in and later check-out are required');const room=db.prepare('SELECT * FROM rooms WHERE id=? AND active=1').get(x.room_id);if(!room)throw Error('Room not found');const clash=db.prepare("SELECT 1 FROM bookings WHERE room_id=? AND status NOT IN ('Cancelled','Checked out') AND check_in<? AND check_out>?").get(room.id,checkOut,checkIn);if(clash)throw Error('Room is already booked for these dates');const nights=Math.max(1,Math.round((Date.parse(checkOut)-Date.parse(checkIn))/86400000)),rate=num(x.rate||room.price_per_night),out=db.transaction(()=>{const g=db.prepare('INSERT INTO guests(name,phone,notes) VALUES(?,?,?)').run(cleanText(x.guest_name,100),cleanText(x.phone,50),cleanText(x.guest_notes,500));return db.prepare('INSERT INTO bookings(guest_id,room_id,check_in,check_out,nights,rate,total,status,payment_status,payment_method,note) VALUES(?,?,?,?,?,?,?,?,?,?,?)').run(g.lastInsertRowid,room.id,checkIn,checkOut,nights,rate,nights*rate,x.status||'Reserved',x.payment_status||'Unpaid',x.payment_method||'',cleanText(x.note,500))})();audit('CREATE','booking',out.lastInsertRowid,`${x.guest_name}, ${room.room_name}`,req.user.username);res.json({id:out.lastInsertRowid,total:nights*rate})}catch(e){res.status(400).json({error:e.message})}});
app.post('/api/accommodation/payments',auth,allow('Administrator/Owner','Manager','Cashier'),(req,res)=>{try{const x=req.body||{};if(num(x.amount)<=0||!x.booking_id)throw Error('Booking and positive amount are required');const r=db.prepare('INSERT INTO accommodation_payments(booking_id,amount,payment_date,payment_method,reference,received_by) VALUES(?,?,?,?,?,?)').run(x.booking_id,num(x.amount),x.payment_date||today(),x.payment_method||'Cash',cleanText(x.reference,120),req.user.username);db.prepare("UPDATE bookings SET payment_status=CASE WHEN total<=(SELECT COALESCE(SUM(amount),0) FROM accommodation_payments WHERE booking_id=?) THEN 'Paid' ELSE 'Part paid' END WHERE id=?").run(x.booking_id,x.booking_id);audit('CREATE','accommodation_payment',r.lastInsertRowid,`Booking ${x.booking_id}: ${x.amount}`,req.user.username);res.json({id:r.lastInsertRowid})}catch(e){res.status(400).json({error:e.message})}});

app.get('/api/reports',auth,(req,res)=>{const from=req.query.from||today(),to=req.query.to||today();const sales=db.prepare('SELECT COALESCE(SUM(total),0) total,COUNT(*) count FROM sales WHERE sale_date BETWEEN ? AND ? AND voided_at IS NULL').get(from,to);const expenses=db.prepare('SELECT COALESCE(SUM(amount),0) total FROM expenses WHERE expense_date BETWEEN ? AND ?').get(from,to);const cogs=db.prepare(`SELECT COALESCE(SUM(si.qty*sm.unit_cost),0) cost FROM sale_items si JOIN sales s ON s.id=si.sale_id JOIN stock_moves sm ON sm.reference='Sale #'||s.id AND sm.product_id=si.product_id AND sm.move_type='SALE' WHERE s.sale_date BETWEEN ? AND ? AND s.voided_at IS NULL`).get(from,to);const products=db.prepare(`SELECT p.id,p.name,p.unit,p.stock,p.buy_price,p.sell_price,p.price_estimated_buy,p.price_estimated_sell,COALESCE(SUM(CASE WHEN sm.move_type='SALE' AND sm.move_date BETWEEN ? AND ? THEN sm.qty ELSE 0 END),0) sold,COALESCE(SUM(CASE WHEN sm.move_type IN ('IN','OPENING') AND sm.move_date BETWEEN ? AND ? THEN sm.qty ELSE 0 END),0) received FROM products p LEFT JOIN stock_moves sm ON sm.product_id=p.id WHERE p.active=1 GROUP BY p.id ORDER BY sold DESC`).all(from,to,from,to);const byDay=db.prepare(`SELECT sale_date date,ROUND(SUM(total),2) sales FROM sales WHERE sale_date BETWEEN ? AND ? AND voided_at IS NULL GROUP BY sale_date ORDER BY sale_date`).all(from,to);const byPay=db.prepare('SELECT payment_method,ROUND(SUM(total),2) total FROM sales WHERE sale_date BETWEEN ? AND ? AND voided_at IS NULL GROUP BY payment_method').all(from,to);const byExpense=db.prepare('SELECT category,ROUND(SUM(amount),2) total FROM expenses WHERE expense_date BETWEEN ? AND ? GROUP BY category ORDER BY total DESC').all(from,to);res.json({from,to,sales,expenses,cogs:cogs.cost,gross_profit:sales.total-cogs.cost,profit:sales.total-expenses.total-cogs.cost,products,byDay,byPay,byExpense})});

app.get('/api/price-history',auth,(req,res)=>res.json(db.prepare(`SELECT h.*,p.name product FROM price_history h JOIN products p ON p.id=h.product_id WHERE h.product_id=? ORDER BY h.effective_date DESC,h.id DESC`).all(req.query.product_id)));
app.post('/api/price-history',auth,allow('Administrator/Owner','Manager'),(req,res)=>{const x=req.body;db.prepare(`INSERT INTO price_history(product_id,price_type,price,effective_date,estimated,source_note) VALUES(?,?,?,?,?,?)`).run(x.product_id,x.price_type,x.price,x.effective_date||today(),x.estimated?1:0,x.source_note||'');res.json({ok:true})});

app.get('/api/closing',auth,(req,res)=>{const d=req.query.date||today();const opening=db.prepare('SELECT opening_cash FROM daily_closings WHERE close_date=?').get(d)?.opening_cash||0;const sales=db.prepare(`SELECT payment_method,COALESCE(SUM(total),0) total FROM sales WHERE sale_date=? AND voided_at IS NULL GROUP BY payment_method`).all(d);const by=Object.fromEntries(sales.map(x=>[x.payment_method,x.total]));const exp=db.prepare('SELECT COALESCE(SUM(amount),0) total FROM expenses WHERE expense_date=?').get(d).total;const expected=num(opening)+num(by.Cash)-num(exp);const closed=db.prepare('SELECT * FROM daily_closings WHERE close_date=?').get(d);res.json({date:d,opening_cash:opening,cash_sales:by.Cash||0,mpesa_sales:by['M-Pesa']||0,card_sales:by.Card||0,other_sales:by.Other||0,expenses:exp,expected_cash:expected,closing:closed||null})});
app.post('/api/closing',auth,allow('Administrator/Owner','Manager'),(req,res)=>{try{const x=req.body||{},d=x.close_date||today();if(!validDate(d))throw Error('Enter a valid closing date');const sales=db.prepare(`SELECT payment_method,COALESCE(SUM(total),0) total FROM sales WHERE sale_date=? AND voided_at IS NULL GROUP BY payment_method`).all(d);const by=Object.fromEntries(sales.map(y=>[y.payment_method,y.total]));const exp=db.prepare('SELECT COALESCE(SUM(amount),0) total FROM expenses WHERE expense_date=?').get(d).total;const expected=num(x.opening_cash)+num(by.Cash)-num(exp);const actual=num(x.actual_cash);const diff=actual-expected;db.prepare(`INSERT INTO daily_closings(close_date,opening_cash,cash_sales,mpesa_sales,card_sales,other_sales,expenses,expected_cash,actual_cash,difference,closed_at,closed_by,note) VALUES(?,?,?,?,?,?,?,?,?,?,datetime('now'),?,?) ON CONFLICT(close_date) DO UPDATE SET opening_cash=excluded.opening_cash,cash_sales=excluded.cash_sales,mpesa_sales=excluded.mpesa_sales,card_sales=excluded.card_sales,other_sales=excluded.other_sales,expenses=excluded.expenses,expected_cash=excluded.expected_cash,actual_cash=excluded.actual_cash,difference=excluded.difference,closed_at=excluded.closed_at,closed_by=excluded.closed_by,note=excluded.note`).run(d,num(x.opening_cash),by.Cash||0,by['M-Pesa']||0,by.Card||0,by.Other||0,exp,expected,actual,diff,req.user.username,cleanText(x.note,500));audit('CLOSE','daily_closing',null,`${d} difference ${diff}`,req.user.username);res.json({date:d,expected_cash:expected,actual_cash:actual,difference:diff})}catch(e){res.status(400).json({error:e.message})}});

app.get('/api/audit',auth,allow('Administrator/Owner','Manager'),(req,res)=>res.json(db.prepare('SELECT * FROM audit_log ORDER BY id DESC LIMIT 300').all()));
app.get('/api/backup',auth,allow('Administrator/Owner'),(req,res)=>{const out=path.join(path.dirname(dbPath),`club-backup-${Date.now()}.db`);db.pragma('wal_checkpoint(TRUNCATE)');fs.copyFileSync(dbPath,out);res.download(out,'park-bar-backup.db',()=>{try{fs.unlinkSync(out)}catch{}})});
app.get('/api/settings',auth,(req,res)=>res.json(Object.fromEntries(db.prepare('SELECT key,value FROM settings').all().map(x=>[x.key,x.value]))));
app.use((req,res,next)=>{if(req.path.startsWith('/api/')) return res.status(404).json({error:'Not found'});next()});
function startServer(port) {
 const server=app.listen(port,()=>console.log(`Park Bar Club Manager running at http://localhost:${port}`));
 server.once('error',(error)=>{
  if(error.code==='EADDRINUSE'&&!process.env.PORT&&port<3010){
   console.warn(`Port ${port} is already in use; trying port ${port+1}.`);
   startServer(port+1);
   return;
  }
  throw error;
 });
}
if (require.main === module) startServer(PORT);

